#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int T;    cin >> T;     while(T--){        ll n, k, q;        cin >> n >> k >> q;         vector<ll> a(n);        for(int i = 0; i < n; i++){            cin >> a[i];        }         ll len = 0;        ll ans = 0;         for(int i = 0; i < n; i++){            if(a[i] <= q){                len++;            }            else{                if(len >= k){                    ll x = len - k + 1;                    ans += x * (x + 1) / 2;                }                len = 0;            }        }         // last segment        if(len >= k){            ll x = len - k + 1;            ans += x * (x + 1) / 2;        }         cout << ans << "\n";    }}